from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Locate separated non-background bands; matching bands are repeated shapes.
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    best_marks = []
    best_score = 0
    for i, (a, b) in enumerate(bands):
        for c, d in bands[i + 1:]:
            if b - a != d - c:
                continue
            marks = []
            for ra, rb in zip(range(a, b), range(c, d)):
                # Mark only trailing background cells where the aligned copy has foreground.
                for col in range(w - 1, -1, -1):
                    if grid[ra][col] == bg:
                        if grid[rb][col] != bg:
                            marks.append((ra, col))
                    else:
                        break
                for col in range(w - 1, -1, -1):
                    if grid[rb][col] == bg:
                        if grid[ra][col] != bg:
                            marks.append((rb, col))
                    else:
                        break
            # Choose the most informative repeated-band match.
            if len(marks) > best_score:
                best_score, best_marks = len(marks), marks

    out = [row[:] for row in grid]
    for rr, cc in best_marks:
        out[rr][cc] = 1
    return out

def transform(grid):
    """Overlay binary panels above and below the uniform divider; mark overlaps as 2."""
    divider = next(r for r, row in enumerate(grid)
                   if len(set(row)) == 1 and row[0] != 0)
    top = grid[:divider]
    bottom = grid[divider + 1:]
    if len(top) != len(bottom):
        raise ValueError("panels have different heights")
    return [[2 if a != 0 and b != 0 else 0 for a, b in zip(upper, lower)]
            for upper, lower in zip(top, bottom)]

